SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='102c3834-a7c5-5657-8e67-858c3bfce210'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('f2dca0e7-5391-53ef-b9a8-75a62ef99fac','436c9f60-1940-5a35-a737-57729c17bc78')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='102c3834-a7c5-5657-8e67-858c3bfce210'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='102c3834-a7c5-5657-8e67-858c3bfce210'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('f2dca0e7-5391-53ef-b9a8-75a62ef99fac','436c9f60-1940-5a35-a737-57729c17bc78')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='102c3834-a7c5-5657-8e67-858c3bfce210'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
