 JOIN app.customer_profile_lifecycle_event h ON h.id='fb1f582e-61b8-5289-91c7-482910c4f765' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='68e7beab-0750-549b-9939-b72874954f84' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
