  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"102c3834-a7c5-5657-8e67-858c3bfce210"},"prior":null,"committed":{"id":"102c3834-a7c5-5657-8e67-858c3bfce210","userId":"28c6ee04-0d6e-5cc3-939e-ba10818c288c","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='102c3834-a7c5-5657-8e67-858c3bfce210' AND c.user_id='28c6ee04-0d6e-5cc3-939e-ba10818c288c' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
